def sum_Of_product(n):
    total = 0
    for k in range(1, n + 1):
        term_n_minus_1_k_minsus_1 = (n - 1) * binomial_coefficient(n - 2, k - 1) if k > 1 else 0
        term_n_k = binomial_coefficient(n, k)
        total += term_n_minus_1_k_minsus_1 * term_n_k
    return total

def binomial_coefficient(n, k):
    from math import comb
    return comb(n, k) if n >= 0 and 0 <= k <= n else 0
